import{at as e,it as t,t as n,yt as r}from"./chunks/framework.CNl5aO3-.js";var i=JSON.parse(`{"title":"Migrate belongsTo and hasMany Fields to resource and collection","description":"","frontmatter":{},"headers":[],"relativePath":"skills/relationships/migrate-relationship-fields.md","filePath":"skills/relationships/migrate-relationship-fields.md"}`),a={name:`skills/relationships/migrate-relationship-fields.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="migrate-belongsto-and-hasmany-fields-to-resource-and-collection" tabindex="-1">Migrate belongsTo and hasMany Fields to resource and collection <a class="header-anchor" href="#migrate-belongsto-and-hasmany-fields-to-resource-and-collection" aria-label="Permalink to “Migrate belongsTo and hasMany Fields to resource and collection”">​</a></h1><p>Use this skill whenever you are changing a schema&#39;s <code>belongsTo</code> or <code>hasMany</code> field to the <code>resource</code> or <code>collection</code> kind, or a user asks to move relationships to &quot;the new kinds&quot;, &quot;PolarisMode relationships&quot;, or &quot;relationship documents&quot;. The human guide <a href="/pr-preview/pr-11248/upgrading/v5/relationships">Migrating Relationships to <code>resource</code> and <code>collection</code></a> owns the rules; this skill is the order to apply them in and the checks that catch a field that must not be migrated yet.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to “Steps”">​</a></h2><ol><li>Confirm the field lives on a <code>ReactiveResource</code> schema (<code>store.schema.registerResource</code> or a schema file), not on a <code>Model</code> decorated with <code>@belongsTo</code>/<code>@hasMany</code>. The new kinds have no decorator form. If the app is still on <code>Model</code>, stop and point the user at <a href="/pr-preview/pr-11248/guides/the-manual/schemas/resources/legacy-mode#migration">LegacyMode → Migration</a> first.</li><li>For each field, establish what the API sends for it by reading the payloads the app actually receives (test fixtures, mock handlers, recorded responses), and if none are available, ask the user. Classify the field with the table in <a href="/pr-preview/pr-11248/upgrading/v5/relationships#step-1-classify-each-relationship">Step 1: Classify Each Relationship</a>: members always delivered with the parent means <code>async: false</code>; a <code>links.related</code> link means <code>async: true</code>. The field&#39;s current <code>async</code> value is not the answer, because the option&#39;s meaning changes.</li><li>Before converting, check for the two patterns that have <a href="/pr-preview/pr-11248/upgrading/v5/relationships#patterns-without-a-migration-path">no migration path</a>: <ul><li>payloads whose relationship <code>data</code> references resources that are not in the same payload&#39;s <code>data</code> or <code>included</code>;</li><li>code calling <code>.belongsTo(&#39;&lt;name&gt;&#39;).id()</code> or <code>.hasMany(&#39;&lt;name&gt;&#39;).ids()</code> on that field, or passing ids taken from it to <code>findRecord</code>. If either is present in any endpoint that delivers the field, leave the field on <code>belongsTo</code>/<code>hasMany</code> untouched, tell the user why, and mention that the <code>reference</code> and <code>pointer</code> field kinds proposed in an upcoming RFC are the intended upgrade path. Legacy and migrated fields coexist, including as each other&#39;s inverse.</li></ul></li><li>If the field is <code>async: true</code> today and is consumed implicitly (an <code>#each</code> over <code>record.&lt;name&gt;</code>, <code>.content</code>, getters reading through it), migrate that usage first with <a href="./migrate-async-relationship-usage">Migrate Async Relationship Usage</a>; the field change alone breaks those sites. Step 6 below then covers the remaining, explicit reads.</li><li>Convert the field as shown in <a href="/pr-preview/pr-11248/upgrading/v5/relationships#step-2-convert-the-field">Step 2: Convert the Field</a>: change <code>kind</code>, set <code>async</code> from step 2, keep <code>inverse</code>, <code>polymorphic</code>, <code>as</code> and <code>sourceKey</code>, drop <code>linksMode</code> and <code>resetOnRemoteUpdate</code> (the new kinds always load through requests, so nothing replaces <code>linksMode</code>). Update the TypeScript interface so the property is a <code>ReactiveRelationshipDocument&lt;T&gt;</code> from <code>@warp-drive/core/reactive</code>.</li><li>Update every read and write of the field using the tables in <a href="/pr-preview/pr-11248/upgrading/v5/relationships#step-3-update-reads">Step 3: Update Reads</a> and <a href="/pr-preview/pr-11248/upgrading/v5/relationships#step-4-update-writes">Step 4: Update Writes</a>. Search for the field name followed by <code>.content</code>, for <code>await</code> of the field, and for <code>.belongsTo(</code>/<code>.hasMany(</code> reference calls on it; none of these has a meaning on a relationship document.</li><li>For every <code>async: true</code> field, make sure something loads it, following <a href="/pr-preview/pr-11248/upgrading/v5/relationships#step-5-load-async-relationships">Step 5: Load Async Relationships</a>. Prefer adding the relationship to the <code>include</code> of the request that loads the parent; use <code>doc.fetch()</code> or a <code>&lt;Request /&gt;</code> on <code>doc.links.related</code> only for relationships loaded on demand. <code>doc.fetch()</code> fills in <code>doc.data</code>; a <code>&lt;Request /&gt;</code> does not, so render its response.</li><li>Run the app&#39;s tests with the JSON:API validator active and fix what it reports in the payloads (fixtures, mocks, or the API) rather than by weakening the schema. The <a href="/pr-preview/pr-11248/guides/the-manual/relational-data/spec#_3-4-enforcement">Relationship Specification</a> lists the rules and says how the validator is enabled.</li></ol><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to “Related”">​</a></h2><ul><li>Full guide: <a href="/pr-preview/pr-11248/upgrading/v5/relationships">Migrating Relationships to <code>resource</code> and <code>collection</code></a></li><li>Field reference: <a href="/pr-preview/pr-11248/guides/the-manual/schemas/relational-fields">Relational Fields</a></li><li>Related skill: <a href="./../schemas/define-a-resource-schema">Define a Resource Schema</a></li></ul>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};